pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    const HELLO_PREFIX: &str = "v:2|hello|";
    if let Some(name) = bytes.strip_prefix(HELLO_PREFIX) {
        return Ok(Msg::Hello(name.into()));
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello|{name}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn encode_roundtrip(msg: &Msg) -> Result<Msg, String> {
        decode(&encode(msg))
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(encode_roundtrip(&Msg::Ping), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_uses_v2_envelope_and_roundtrips() {
        let msg = Msg::Hello("Ada Lovelace".into());

        assert_eq!(encode(&msg), "v:2|hello|Ada Lovelace");
        assert!(matches!(
            encode_roundtrip(&msg),
            Ok(Msg::Hello(name)) if name == "Ada Lovelace"
        ));
    }

    #[test]
    fn hello_payload_is_opaque() {
        let msg = Msg::Hello("Ada|Lovelace".into());

        assert!(matches!(
            encode_roundtrip(&msg),
            Ok(Msg::Hello(name)) if name == "Ada|Lovelace"
        ));
    }

    #[test]
    fn unsupported_versions_are_rejected() {
        assert!(matches!(decode("v:1|hello|Ada"), Err(error) if error == "unknown"));
    }
}
